322	   * Operator steering while work runs. Held by the agent and applied at its next step boundary; if the turn is already
323	   * finishing it starts a follow-up turn; if nothing is running it starts a turn. Never applied twice, never dropped
324	   * without telling the client (which then gets the text back).
325	   */
326	  private steer(id: string, text: string): void {
327	    // Seen by this process, or recorded in the session's objective ledger (applied before a restart and resume).
328	    if (this.steerSeen.has(id) || this.app.getAgent().getObjective()?.steering.some((s) => s.id === id)) {
329	      this.steerAck(id, "duplicate", "Already received; it is not applied again.");
330	      return;
331	    }
332	    this.steerSeen.add(id);
333	    if (this.shutdownPromise) {
334	      this.steerAck(id, "rejected", "The sidecar is shutting down; your message was not applied.", text);
335	      return;
336	    }
337	    if (!this.activeTurn) {
338	      this.runJob(id, undefined, (signal) =>
339	        this.gatedTurn(id, text, signal, {
340	          admitted: () => {
341	            this.history.push(text.trim());
342	            this.steerAck(id, "applied", "Nothing was running, so your message started a new turn.");
343	          },
344	          refused: (message) => this.steerAck(id, "cancelled", `${message} Your message is back in the composer.`, text),
345	        }),
346	      );
347	      return;
348	    }
349	    if (this.activeSpec) {
350	      const name = this.activeSpec.name === "!" ? "!" : `/${this.activeSpec.name}`;
351	      this.steerAck(id, "rejected", `${name} is running, and steering applies to agent turns; your message is back in the composer.`, text);
352	      return;
353	    }
354	    const queued = this.app.getAgent().queueSteering(id, text);
355	    if (queued.status === "queued") {
356	      this.history.push(text.trim());
357	      this.steerAck(id, "queued", "Steering queued; the agent applies it at its next step.");
358	      return;
359	    }
360	    if (queued.status === "duplicate") {
361	      this.steerAck(id, "duplicate", "Already received; it is not applied again.");
362	      return;
363	    }
364	    this.followUps.push({ id, text });
365	    this.steerAck(id, "deferred", "The turn is finishing; your message starts a follow-up turn as soon as it ends.");
366	  }
367	
368	  /** Runs deferred steering as one follow-up turn under the first message's id. */
369	  private startFollowUp(): void {
370	    const followUps = this.followUps;
371	    this.followUps = [];
372	    const id = followUps[0].id;
373	    const text = followUps.map((f) => f.text).join("\n\n");
374	    this.runJob(id, undefined, (signal) =>
375	      this.gatedTurn(id, text, signal, {
376	        admitted: () => {
377	          for (const f of followUps) {
378	            this.history.push(f.text.trim());
379	            this.steerAck(f.id, "applied", "Applied as a follow-up turn.");
380	          }
381	        },
382	        refused: (message) => {
383	          for (const f of followUps) this.steerAck(f.id, "cancelled", `${message} Your message is back in the composer.`, f.text);
384	        },
385	      }),
386	    );
387	  }
388	
389	  private cancel(): void {
390	    for (const f of this.followUps) this.steerAck(f.id, "cancelled", "Cancelled with the turn before it could start; your message is back in the composer.", f.text);
391	    this.followUps = [];
392	    this.dropPendingCompactions("cancelled with the running work");
393	    const spec = this.activeSpec;
394	    if (this.activeTurn && spec && !spec.cancellable) {
395	      const name = spec.name === "!" ? "!" : `/${spec.name}`;
396	      this.emit({ type: "notice", text: `${name} cannot be cancelled; it finishes on its own.` });
397	      return;
398	    }
399	    this.turnAbort?.abort(new Error("operator cancel"));
400	  }
401	
402	  /** Reports BUSY for `id` when a turn or command is running or the sidecar is shutting down. */
403	  private rejectBusy(id: string): boolean {
404	    if (!this.shutdownPromise && !this.activeTurn) return false;
405	    const message = this.shutdownPromise ? "The sidecar is shutting down." : "A turn or command is running; cancel it or wait for its result.";
406	    this.emit({ type: "error", id, code: "BUSY", message });
407	    return true;
408	  }
409	
410	  /**
411	   * /compact while a turn or command runs. During an agent turn the agent holds it until the turn's next step boundary
412	   * (after the in-flight inference and its tool batch, approvals included, have settled) or the turn's end. While another
413	   * command runs, it waits here and runs as its own job afterwards. Each request is acknowledged now (notice) and gets
414	   * its outcome later (slash.result for its id). A duplicate shares the queued request's outcome; at most one request
415	   * per kind (default, --llm) waits; cancellation and shutdown end waiting requests with that outcome.
416	   */
417	  private queueCompaction(id: string, llm: boolean): void {
418	    const queued = this.app.getAgent().requestCompaction(id, llm);
419	    if (queued.status !== "no_active_turn") {
420	      this.emit({ type: "notice", text: queued.message });
421	      return;
422	    }
423	    const existing = this.pendingCompactions.find((p) => p.llm === llm);
424	    if (existing) {
425	      existing.ids.push(id);
426	      this.emit({ type: "notice", text: `A /compact${llm ? " --llm" : ""} is already waiting; this request shares its outcome.` });
427	      return;
428	    }
429	    this.pendingCompactions.push({ ids: [id], llm });
430	    this.emit({ type: "notice", text: `/compact${llm ? " --llm" : ""} queued: it runs when the current command finishes.` });
431	  }
432	
433	  private compactionResult(ids: string[], ok: boolean, message: string): void {
434	    for (const id of ids) this.emit({ type: "slash.result", id, command: "compact", success: ok, output: message });
435	  }
436	
437	  /** Ends waiting /compact requests that will not run. */
438	  private dropPendingCompactions(reason: string): void {
439	    for (const p of this.pendingCompactions) this.compactionResult(p.ids, false, `/compact was not run: ${reason}.`);
440	    this.pendingCompactions = [];
441	  }
442	
443	  /** Runs one turn or command as the session's only activity. Busy is reported before `body` starts. */
444	  private runJob(id: string, spec: SlashSpec | undefined, body: (signal: AbortSignal) => Promise<void>): void {
445	    const abort = new AbortController();
446	    this.turnAbort = abort;
447	    this.activeSpec = spec;
448	    let settle!: () => void;
449	    this.activeTurn = new Promise<void>((resolve) => {
450	      settle = resolve;
451	    });
452	    this.emitSessionState();
453	    void body(abort.signal)
454	      .catch((err) => this.emit({ type: "error", id, code: "INTERNAL", message: errorText(err) }))
455	      .finally(() => {
456	        this.activeTurn = undefined;
457	        this.turnAbort = undefined;
458	        this.activeSpec = undefined;
459	        // Queued /compact runs before anything else starts, without an idle state in between.
460	        if (this.pendingCompactions.length && !this.shutdownPromise) {
461	          const pending = this.pendingCompactions;
462	          this.pendingCompactions = [];
463	          settle();
464	          this.runJob(pending[0].ids[0], findSlash("compact"), async (signal) => {
465	            for (const p of pending) {
466	              const result = await this.app.getAgent().compactNow(p.llm, signal);
467	              this.compactionResult(p.ids, result.ok, result.message);
468	            }
469	          });
470	          return;
471	        }
472	        if (this.pendingCompactions.length) this.dropPendingCompactions("the sidecar is shutting down");
473	        // Deferred steering starts its turn without an idle state in between, so nothing can slip into the gap.
474	        if (this.followUps.length && !this.shutdownPromise) {
475	          settle();
476	          this.startFollowUp();
477	          return;
478	        }
479	        this.emitSessionState();
480	        settle();
481	      });
482	  }
483	
484	  private submit(id: string, text: string): void {
485	    if (this.rejectBusy(id)) return;
486	    this.runJob(id, undefined, (signal) =>
487	      this.gatedTurn(id, text, signal, {
488	        admitted: () => this.history.push(text.trim()),
489	        refused: (message) => this.emit({ type: "error", id, code: "NO_PROVIDER", message }),
490	      }),
491	    );
492	  }
493	
494	  /**
495	   * The one way a prompt, a steer that starts a turn and a follow-up start a turn. When start-up found nothing answering,
496	   * it waits for that probe, asks again (the operator may have connected a provider or started a server since) and
497	   * refuses with the reason rather than entering a retry loop. A cancelled probe says nothing about the provider: the
498	   * gate stays and the turn does not run.
499	   */
500	  private async gatedTurn(
501	    id: string,
502	    text: string,
503	    signal: AbortSignal,
504	    hooks: { admitted?: () => void; refused: (message: string) => void },
505	  ): Promise<void> {
506	    await this.startupProbe;
507	    if (this.providerProblem) {
508	      const problem = await this.app.getAgent().probeEndpointProblem(signal);
509	      if (signal.aborted) return;
510	      this.providerProblem = problem?.kind === "unreachable" ? problem : undefined;
511	      if (this.providerProblem) {
512	        hooks.refused(noProviderRefusal(this.providerProblem));
513	        return;
514	      }
515	    }
516	    hooks.admitted?.();
517	    await this.turn(id, text, text, `Turn: ${text.slice(0, 30)}`, signal);
518	  }
519	
520	  private observerFor(turnId: string): AgentObserver {
521	    const open = new Map<number, string>();
522	    // The evidence ledger is a sink of its own, so its copy of the tool name is sanitized before it is stored; the events carry the raw name.
523	    return {
524	      onAssistantDelta: (delta) => this.emit({ type: "assistant.delta", turn_id: turnId, text: delta }),
525	      onToolStart: ({ dispatch, callId, tool: rawTool, args }) => {
526	        const tool = rawTool;
527	        const subject = toolSubject(args);
528	        const evidence = this.evidence.start(turnId, redactThenCap(rawTool, 200), subject, args);
529	        open.set(dispatch, evidence);
530	        this.emit({ type: "tool.start", turn_id: turnId, call_id: callId, tool, subject, evidence });
531	      },
532	      onToolEnd: ({ dispatch, callId, tool: rawTool, success, output, error }) => {
533	        const tool = rawTool;
534	        const evidence = open.get(dispatch) ?? "";
535	        open.delete(dispatch);
536	        this.evidence.end(evidence, success, output, error);
537	        const summary = toolSummary(success, output, error);
538	        this.emit({
539	          type: "tool.end", turn_id: turnId, call_id: callId, tool, success, evidence,
540	          ...summary,
541	        });
542	      },
543	      onProviderRecovery: ({ record, discardedPartialOutput }) => {
544	        const status = providerRecoveryStatus(record, discardedPartialOutput);
545	        if (status) this.emit({ type: "notice", ...status });
546	      },
547	      onActivity: ({ phase, step, segment, tool, subject }) =>
548	        this.emit({
549	          type: "activity",
550	          turn_id: turnId,
551	          phase,
552	          step,
553	          segment,
554	          ...this.budget(),
555	          ...(tool ? { tool: tool } : {}),
556	          ...(subject ? { subject: subject } : {}),
557	        }),
558	      onFileChange: ({ dispatch, callId, path: file, change }) => {
559	        const evidence = open.get(dispatch) ?? "";
560	        const safe = formatSafeSidecarText(change.diff);
561	        const fullPath = this.keepOperationDiff(evidence, callId, safe);
562	        this.evidence.attachDiff(evidence, safe, fullPath);
563	        const { preview, truncated, totalLines } = previewDiff(safe, DIFF_PREVIEW_LINES, DIFF_PREVIEW_CHARS);
564	        this.emit({
565	          type: "file.diff",
566	          turn_id: turnId,
567	          call_id: callId,
568	          evidence,
569	          path: file,
570	          kind: change.kind,
571	          added: change.added,
572	          removed: change.removed,
573	          preview,
574	          truncated,
575	          total_lines: totalLines,
576	          diff_lines: countDiffLines(safe),
577	          hunks: change.hunks ?? 0,
578	          ...(fullPath ? { full_path: fullPath } : {}),
579	          ...(change.note ? { note: change.note } : {}),

