617	  /** One agent turn: checkpoint, run, save the session, report the result. `step`: one cycle of the unfinished objective. */
618	  private async turn(turnId: string, prompt: string | any[], label: string, checkpoint: string, signal: AbortSignal, step = false): Promise<void> {
619	    const agent = this.app.getAgent();
620	    let allowSensitiveCheckpoint = false;
621	    try {
622	      agent.enterNamedWorktreeBeforeTurn(); // the snapshot is of the worktree the turn edits
623	    } catch (err) {
624	      this.emit({ type: "error", id: turnId, code: "INTERNAL", message: formatSafeSidecarText(errorText(err)) });
625	      return;
626	    }
627	    if (this.app.getConfig().readOnly) {
628	      // Read-only turns cannot change the workspace, so a workspace rollback snapshot is unnecessary.
629	      agent.setCheckpointReadOnlyFallback(false);
630	    } else {
631	      let checkpointReady = false;
632	      while (!checkpointReady) {
633	        try {
634	          this.app.getCheckpointManager().createCheckpoint(
635	            checkpoint,
636	            allowSensitiveCheckpoint ? { allowSensitive: true } : undefined,
637	          );
638	          const previousApprovalMode = agent.getApprovalMode();
639	          agent.setCheckpointReadOnlyFallback(false);
640	          if (agent.getApprovalMode() !== previousApprovalMode) this.emitSessionState();
641	          checkpointReady = true;
642	        } catch (err) {
643	          const sensitiveContentBlocked = err instanceof SensitivePersistenceError;
644	          const failure = capText(
645	            formatSafeSidecarText(errorText(err))
646	              .replace(/\s+/g, " ")
647	              .trim()
648	              .replace(/;\s*no checkpoint was written\.?$/i, ""),
649	            100,
650	          );
651	          const message = sensitiveContentBlocked
652	            ? undefined
653	            : `Checkpoint failed: ${failure}. No checkpoint was written. Choose 1 read-only, 2 continue without a rollback checkpoint, 3 retry checkpoint normally, 4 cancel this turn, or 5 re-enter the instruction.`;
654	          const choices: readonly CheckpointChoice[] = sensitiveContentBlocked
655	            ? ["read_only", "without_checkpoint", "allow_sensitive", "cancel", "other"]
656	            : ["read_only", "without_checkpoint", "retry", "cancel", "other"];
657	          const choice = await this.requestCheckpointChoice(turnId, signal, message, choices);
658	          if (choice === "cancel" || choice === "other") {
659	            const message = choice === "other"
660	              ? "This turn was not started. Enter a different instruction in the composer."
661	              : "This turn was cancelled before it started.";
662	            this.emit({ type: "error", id: turnId, code: "INTERNAL", message });
663	            return;
664	          }
665	          if (choice === "read_only") {
666	            agent.setCheckpointReadOnlyFallback(true);
667	            this.emit({ type: "notice", text: "Continuing this turn in read-only mode as requested. Workspace changes, unsafe commands, external actions, and delegation are disabled." });
668	            this.emitSessionState();
669	            checkpointReady = true;
670	          } else if (choice === "without_checkpoint") {
671	            const previousApprovalMode = agent.getApprovalMode();
672	            agent.setCheckpointReadOnlyFallback(false);
673	            if (agent.getApprovalMode() !== previousApprovalMode) this.emitSessionState();
674	            this.emit({ type: "notice", text: "Continuing in the current mode without a rollback checkpoint, as requested." });
675	            checkpointReady = true;
676	          } else if (choice === "retry") {
677	            this.emit({ type: "notice", text: "Retrying checkpoint without changing sensitive-persistence settings. The turn remains paused until the retry succeeds or you choose another option." });
678	          } else if (choice === "allow_sensitive") {
679	            allowSensitiveCheckpoint = true;
680	            this.emit({ type: "notice", text: "Retrying checkpoint with sensitive persistence allowed, as requested; this may persist sensitive workspace content. The turn will wait until the retry succeeds or you choose another option." });
681	          }
682	        }
683	      }
684	    }
685	    if (typeof prompt === "string" && !step) {
686	      const decision = agent.objectiveDecision(prompt);
687	      if (decision.kind === "amend") {
688	        this.emit({
689	          type: "notice",
690	          text: `This message continues the unfinished objective (${decision.unresolved} unresolved requirement${decision.unresolved === 1 ? "" : "s"}); its numbered items, if any, are added to it. /requirements clear starts a new objective.`,
691	        });
692	      }
693	    }
694	    agent.setObserver(this.observerFor(turnId));
695	    this.sessionTitle = label;
696	    // Work done so far, and changes still awaiting verification, survive the process ending mid-turn.
697	    agent.setProgressListener(() => this.saveSession(label));
698	    let turn: TurnResult;
699	    try {
700	      turn = await agent.runTurn(prompt, this.confirmFor(turnId, signal), step ? { signal, step: true, resume: true } : { signal });
701	    } catch (err) {
702	      turn = failedTurnFromError(err, this.app.getConfig().maxSteps, agent.hasUnverifiedChanges());
703	    } finally {
704	      agent.setObserver(undefined);
705	      agent.setProgressListener(() => this.saveSession(this.sessionTitle));
706	    }
707	    let saved: boolean;
708	    try {
709	      saved = withDurableSync(() => this.saveSession(label, turn));
710	    } catch (err) {
711	      saved = false;
712	      this.emit({ type: "notice", text: `The session could not be saved: ${errorText(err)}` });
713	    }
714	    const { heading, line } = summarizeTurn(turn);
715	    const projected = projectTurn(turn);
716	    this.lastTurn = { heading, turn: projected };
717	    const summary = turn.execution === "COMPLETED" ? agent.getCompletionSummary() : undefined;
718	    this.emit({
719	      type: "turn.result",
720	      turn_id: turnId,
721	      heading: heading,
722	      line: line,
723	      turn: projected,
724	      model_summary: summary
725	        ? { summary: summary.summary, ...(summary.notes ? { notes: summary.notes } : {}) }
726	        : null,
727	      saved,
728	    });
729	  }
